#define tempo 5

//begin rot
vec2 rot2(vec2 p, float t) {
    return vec2(cos(t) * p.x -sin(t) * p.y, sin(t) * p.x + cos(t) * p.y);
}
vec3 rotX(vec3 p, float t) {
    return vec3(p.x, rot2(p.yz, t));
}
vec3 rotY(vec3 p, float t) {
    return vec3(p.y, rot2(p.zx, t)).zxy;
}
vec3 rotZ(vec3 p, float t) {
    return vec3(rot2(p.xy, t), p.z);
}
vec3 euler(vec3 p, vec3 t) {
    return rotZ(rotY(rotX(p, t.x), t.y), t.z);
}
//end rot

float boxSDF(vec3 p, vec3 c, vec3 d, float t) {
    p = abs(p - c);
    return length(max(p - d, vec3(0.0))) + min(max(max(p.x - d.x, p.y - d.y), p.z - d.z), 0.0) - t;
}

float sphereSDF(vec3 p, float r) {
    return length(p) - r;
}

float sdTorus( vec3 p, vec2 t )
{
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return length(q)-t.y;
}

float random(float n) {
    return fract(sin(n) * 43758.5453123);
}

float sceneSDF(vec3 p) {
    // BPMからビート時間を計算（60秒 / BPM）
    float beatTime = 60.0 / float(tempo);
    // 現在の時間をビート時間で割って正規化
    float switchTime = mod(iTime, beatTime * 3.0) / beatTime;

    // グリッチエフェクトのパラメータ
    float glitchIntensity = .1;

    // グリッチ効果の計算
    vec3 glitchOffset = vec3(0.0);
    float noise = random(floor(iTime * 30.0));
    glitchOffset = vec3(
            random(p.x * 2.0) * 2.0 - 1.0,
            random(p.y * 2.0) * 2.0 - 1.0,
            random(p.z * 2.0) * 2.0 - 1.0
        ) * glitchIntensity;

    // グリッチを適用した位置で距離関数を計算
    p += glitchOffset;

    float d1 = sphereSDF(p, 1.);
    float d2 = boxSDF(p, vec3(0.0), vec3(.7), 0.0);
    float d3 = sdTorus(p, vec2(.7,.7));

    float t1 = smoothstep(0.0, 1.0, switchTime) - smoothstep(0.7, 1.7, switchTime);
    float t2 = smoothstep(0.7, 1.7, switchTime) - smoothstep(1.4, 2.4, switchTime);
    float t3 = smoothstep(1.4, 2.4, switchTime) - smoothstep(2.1, 3.0, switchTime);

    return mix(d1 * t1 + d2 * t2 + d3 * t3 + random(p.y), d1 * t1 + d2 * t2 + d3 * t3 + random(p.x), random(p.z));
}

vec3 gradSDF(vec3 p) {
    float eps = 0.001;
    return normalize(vec3(
        sceneSDF(p + vec3(eps, 0.0, 0.0)) - sceneSDF(p - vec3(eps, 0.0, 0.0)),
        sceneSDF(p + vec3(0.0, eps, 0.0)) - sceneSDF(p - vec3(0.0, eps, 0.0)),
        sceneSDF(p + vec3(0.0, 0.0, eps)) - sceneSDF(p - vec3(0.0, 0.0, eps))
    ));
}

vec3 renderScene(vec2 p) {
    vec3 t = vec3(iTime * 1.0);
    vec3 cPos = euler(vec3(0.0, 0.0, 2.0), t);
    vec3 cDir = euler(vec3(0.0, 0.0, -1.0), t);
    vec3 cUp = euler(vec3(0.0, 1.0, 0.0), t);
    vec3 cSide = cross(cDir, cUp);

    float targetDepth = 2.0;
    vec3 lDir = euler(vec3(0.0, 0.0, 1.0), t);

    vec3 ray = cSide * p.x + cUp * p.y + cDir * targetDepth;
    vec3 rPos = ray + cPos;
    ray = normalize(ray);

    vec3 color = vec3(0.0);
    for(int i = 0; i < 50; i++) {
        if (sceneSDF(rPos) > 0.001) {
            rPos += sceneSDF(rPos) * ray;
        } else {
            float amb = 0.1;
            float diff = 0.9 * max(dot(normalize(lDir), gradSDF(rPos)), 0.0);
            vec3 col = vec3(1.0, 1.0, 1.0);
            color = col * (diff + amb);
            break;
        }
    }
    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 p = (fragCoord/iResolution.xy) * 2.0 - 1.0;

    // RGB各チャンネルのオフセット
    float offset = 0.01;
    vec3 colR = renderScene(p + vec2(0.0, -offset));     // 赤チャンネル
    vec3 colG = renderScene(p + vec2(0.866*offset, 0.1*offset));   // 緑チャンネル
    vec3 colB = renderScene(p + vec2(-0.866*offset, 0.1*offset));  // 青チャンネル

    // RGB各チャンネルを組み合わせる
    fragColor = vec4(colR.r, colG.g, colB.b, 1.);
}
